const voidWolfSheet=new Image();voidWolfSheet.assetSrc='assets/void-wolf-v1.png';
function voidWolfClip(from,to){let end={...from},length=dist(from,to),steps=Math.max(1,Math.ceil(length/6));for(let i=1;i<=steps;i++){let q={x:from.x+(to.x-from.x)*i/steps,y:from.y+(to.y-from.y)*i/steps};if(!passable(q.x,q.y,22)||!lineClear(end,q,22))break;end=q;}return end;}
function beginVoidWolf(e){let dx=p.x-e.x,dy=p.y-e.y,len=Math.hypot(dx,dy)||1,gate=voidWolfClip(p,{x:p.x+dx/len*130,y:p.y+dy/len*130}),target=voidWolfClip(gate,{x:p.x-dx/len*80,y:p.y-dy/len*80});e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'voidRiftHunt',bespoke:true,windup:1.8,origin:{x:e.x,y:e.y},last:{x:e.x,y:e.y},gate,target,blinked:false,hit:false,valid:dist(gate,p)>=60&&lineClear(e,gate,22)};}
function voidWolfContact(point,start,end){let dx=end.x-start.x,dy=end.y-start.y,d=dx*dx+dy*dy,t=d?Math.max(0,Math.min(1,((point.x-start.x)*dx+(point.y-start.y)*dy)/d)):0,q={x:start.x+dx*t,y:start.y+dy*t};return dist(point,q)<=24+1e-8&&lineClear(q,point);}
const voidWolfAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r11e0')return voidWolfAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='voidRiftHunt'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=260&&clear){beginVoidWolf(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,150*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.blinked&&e.elapsed>=1){if(!a.valid||!passable(a.gate.x,a.gate.y,22)||!lineClear(e,a.gate,22)){e.attack=null;e.state='idle';e.t=1.5;return;}a.blinked=true;e.x=a.gate.x;e.y=a.gate.y;a.last={x:e.x,y:e.y};e.facing=a.target.x-e.x-(a.target.y-e.y)<0?-1:1;playSound('impact',e.x,e.y);}
 if(a.blinked&&e.elapsed>=1.8&&!a.dashDone){let t=Math.min(1,(e.elapsed-1.8)/.4),start={x:e.x,y:e.y},target={x:a.gate.x+(a.target.x-a.gate.x)*t,y:a.gate.y+(a.target.y-a.gate.y)*t},end=voidWolfClip(start,target);e.x=end.x;e.y=end.y;a.last={...end};if(!a.hit&&!(p.inv>0)&&voidWolfContact(p,start,end)){a.hit=true;hurt(80);}if(t>=1||dist(end,target)>.01)a.dashDone=true;}
 if(e.elapsed>=3.2){e.attack=null;e.state='idle';e.t=3;}
};
const voidWolfDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r11e0'||!voidWolfSheet.complete||!voidWolfSheet.naturalWidth||!voidWolfSheet.naturalHeight)return voidWolfDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='voidRiftHunt')f={row:2,col:e.elapsed<1?0:e.elapsed<1.8?1:e.elapsed<2.2?2:3};let q=project(e.x,e.y),sw=voidWolfSheet.naturalWidth/4,sh=voidWolfSheet.naturalHeight/3,w=280,h=w*sh/sw,anchor=[[.84,.84,.84,.84],[.78,.78,.78,.78],[.73,.73,.7,.73]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,voidWolfSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(voidWolfSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const voidWolfSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r11e0'?175:voidWolfSizeBase(e);
const voidWolfGroundBase=drawGroundEffects;drawGroundEffects=()=>{voidWolfGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r11e0'):enemies)){let a=e.attack;if(e.species!=='r11e0'||e.hp<=0||a?.pattern!=='voidRiftHunt'||!a.valid||e.elapsed>2.3||!visibleAt(a.gate.x,a.gate.y))continue;groundRing(a.gate.x,a.gate.y,32,'#c18ef0',3);let from=project(a.gate.x,a.gate.y),to=project(a.target.x,a.target.y);ctx.save();let dx=a.target.x-a.gate.x,dy=a.target.y-a.gate.y,len=Math.hypot(dx,dy)||1,nx=-dy/len*24,ny=dx/len*24;ctx.beginPath();[[a.gate.x+nx,a.gate.y+ny],[a.target.x+nx,a.target.y+ny],[a.target.x-nx,a.target.y-ny],[a.gate.x-nx,a.gate.y-ny]].forEach(([x,y],i)=>{let q=project(x,y);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fillStyle='rgba(173,110,220,.15)';ctx.fill();ctx.strokeStyle=e.elapsed<1.8?'#b78bd8':'#eed4ff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(from.x,from.y);ctx.lineTo(to.x,to.y);ctx.stroke();ctx.restore();}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r11e0',animateEnemy,drawRegionEnemy);
